{"solution_py":""""Normalize event timestamps to UTC without mutating input rows."""
from __future__ import annotations

from collections.abc import Iterable, Mapping
from datetime import datetime, timedelta, timezone, tzinfo
import re
from zoneinfo import ZoneInfo


_OFFSET_RE = re.compile(r"^(?:UTC|GMT)?([+-])(\d{2})(?::?(\d{2}))?$")


def _timezone(value: str) -> tzinfo:
    if value.upper() in {"UTC", "Z", "GMT"}:
        return timezone.utc

    match = _OFFSET_RE.fullmatch(value.upper())
    if match:
        hours = int(match.group(2))
        minutes = int(match.group(3) or "0")
        if hours > 23 or minutes > 59:
            raise ValueError(f"invalid timezone offset: {value}")
        delta = timedelta(hours=hours, minutes=minutes)
        if match.group(1) == "-":
            delta = -delta
        return timezone(delta)

    return ZoneInfo(value)


def _as_datetime(value: object) -> datetime:
    if isinstance(value, datetime):
        return value
    if isinstance(value, str):
        text = value.strip()
        if text.endswith(("Z", "z")):
            text = text[:-1] + "+00:00"
        return datetime.fromisoformat(text)
    raise TypeError("timestamp values must be datetime instances or ISO strings")


def _utc_text(value: object, default_tz: tzinfo) -> str:
    moment = _as_datetime(value)
    if moment.tzinfo is None or moment.utcoffset() is None:
        moment = moment.replace(tzinfo=default_tz)
    moment = moment.astimezone(timezone.utc)
    return moment.isoformat().replace("+00:00", "Z")


def migrate_rows(rows: Iterable[Mapping[str, object]], default_timezone: str) -> list[dict[str, object]]:
    """Return copied rows with their event time represented explicitly in UTC."""
    default_tz = _timezone(default_timezone)
    migrated: list[dict[str, object]] = []

    for row in rows:
        result = dict(row)
        if "occurred_at_utc" in result and result["occurred_at_utc"] is not None:
            result["occurred_at_utc"] = _utc_text(result["occurred_at_utc"], default_tz)
        elif "occurred_at" in result and result["occurred_at"] is not None:
            result["occurred_at_utc"] = _utc_text(result["occurred_at"], default_tz)
        migrated.append(result)

    return migrated
